package handlers.skill.effects;

import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.entity.actor.Player;
import org.l2jmobius.gameserver.entity.item.instance.Item;
import org.l2jmobius.gameserver.mechanics.effects.AbstractEffect;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.mechanics.stats.Stat;
import org.l2jmobius.gameserver.network.SystemMessageId;
import org.l2jmobius.gameserver.network.serverpackets.EtcStatusUpdate;
import org.l2jmobius.gameserver.network.serverpackets.SystemMessage;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * This class handles the {@code Focus Max Momentum} skill effect.<br>
 * It manages the logic for increasing a creature's maximum energy.
 * @author Adry_85
 */
public class FocusMaxMomentum extends AbstractEffect
{
	/**
	 * Creates a new instance of the {@code FocusMaxMomentum} effect.<br>
	 * It initializes the effect using the provided statistics.
	 * @param params The {@code StatSet} containing the required parameters.
	 */
	public FocusMaxMomentum(StatSet params)
	{
	}
	
	/**
	 * Checks if the effect is triggered instantly.<br>
	 * This method returns {@code true} for this specific effect.
	 * @return {@code true} if the effect is instant, otherwise {@code false}.
	 */
	@Override
	public boolean isInstant()
	{
		return true;
	}
	
	/**
	 * Applies the instant effect of a skill to a target.<br>
	 * This method updates the player's charges based on their maximum momentum.<br>
	 * It also sends a system message and status update to the affected player.
	 * @param effector The creature performing the action.
	 * @param effected The creature receiving the effect.
	 * @param skill The {@code Skill} being used.
	 * @param item The {@code Item} associated with the skill.
	 */
	@Override
	public void instant(Creature effector, Creature effected, Skill skill, Item item)
	{
		if (effected.isPlayer())
		{
			final Player player = effected.asPlayer();
			
			final int count = (int) effected.getStat().getValue(Stat.MAX_MOMENTUM);
			
			player.setCharges(count);
			
			final SystemMessage sm = new SystemMessage(SystemMessageId.YOUR_FORCE_HAS_INCREASED_TO_LEVEL_S1);
			sm.addInt(count);
			player.sendPacket(sm);
			
			player.sendPacket(new EtcStatusUpdate(player));
		}
	}
}
